inputs = ['jjggy', 'ycgxae', 'yhdwg', 'yev', 'ykzewx']
outputs = ['jjjyejyey', 'ycjyexajwj', 'yhdwjye', 'yjwjv', 'ykzcdx']

print("Analyzing differences:")
for i in range(len(inputs)):
    inp = inputs[i]
    outp = outputs[i]
    print(f"{i}: '{inp}' -> '{outp}'")

    # Show positions where they differ
    diff_positions = []
    for j in range(min(len(inp), len(outp))):
        if inp[j] != outp[j]:
            diff_positions.append((j, inp[j], outp[j]))

    if len(outp) > len(inp):
        for j in range(len(inp), len(outp)):
            diff_positions.append((j, '_', outp[j]))
    elif len(inp) > len(outp):
        for j in range(len(outp), len(inp)):
            diff_positions.append((j, inp[j], '_'))

    if diff_positions:
        print(f"  Differences at positions: {diff_positions}")
    else:
        print("  No differences")
    print()

